def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = b
        else:
            chain_dict[a] = chain_dict[b]

    current = chain_dict['a']
    result = []
    while current in chain_dict:
        result.append(current)
        current = chain_dict[current]
    result.append(current)
    return ','.join(result)
